insert into passages (id, text, difficulty_level, b, active) values
('e0539593-0ef1-4965-91b3-7626bea45c15', 'In a small town, a group of neighbors decided to start a community garden. They found an empty lot behind the school and asked the town for permission to use it. Everyone helped clear the land, and soon they planted vegetables, flowers, and herbs. Families visited the garden every weekend to water the plants and pull out weeds. Children learned how food grows, and older residents shared gardening tips. By the end of summer, the garden was full of tomatoes, carrots, and sunflowers. The neighbors shared the vegetables with everyone in the town, and the garden became a place where people could meet and talk.', 1, -2.0, true),
('55aa6fc8-c55e-4c73-bd29-9598fc65eebb', 'Modern consumers are often presented with an overwhelming array of options, from dozens of cereal brands to hundreds of streaming services. Conventional economic theory suggests that greater choice should lead to greater satisfaction, since individuals are better able to select the option that precisely matches their preferences. However, psychological research has increasingly challenged this assumption. Studies show that when confronted with excessive choice, people frequently experience heightened anxiety, decision paralysis, and post-decision regret. This phenomenon, sometimes termed the paradox of choice, suggests that beyond a certain threshold, additional options impose a cognitive burden rather than conferring genuine benefit. Some researchers argue that this burden arises because evaluating numerous alternatives requires substantial mental effort, and the fear of choosing incorrectly grows as the number of possibilities increases. Businesses have begun to respond to these findings by deliberately curating smaller, more manageable selections for consumers, betting that simplicity, rather than abundance, may ultimately drive both satisfaction and sales.', 5, 2.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('a8ea4dab-2549-4bd9-b236-983b823d4f87', 'sentence_completion', 'The soup was too ___ to eat, so she waited for it to cool down.', NULL, '[{"id": "d", "text": "hot"}, {"id": "c", "text": "quiet"}, {"id": "a", "text": "sweet"}, {"id": "b", "text": "cold"}]'::jsonb, 0, '{"strategy": "המרק חם מדי לאכילה = צריך לחכות שיתקרר.", "correct_reason": "hot = חם. מרק חם מדי דורש המתנה לפני אכילה.", "options_analysis": ["נכון! hot = חם — חם מדי לאכילה", "quiet = שקט — לא מתאר מרק", "sweet = מתוק — לא קשור לטמפרטורה", "cold = קר — קר לא דורש המתנה"]}', 1.46, -2.0, 0.25, 1, 'ai', NULL, true),
('7e671302-99ce-43d6-b94e-4322e649f074', 'sentence_completion', 'He was very ___ because he won first prize in the competition.', NULL, '[{"id": "b", "text": "angry"}, {"id": "c", "text": "proud"}, {"id": "a", "text": "sad"}, {"id": "d", "text": "thirsty"}]'::jsonb, 1, '{"strategy": "won first prize = זכה במקום ראשון. איך מרגישים אחרי ניצחון?", "correct_reason": "proud = גאה. ניצחון בתחרות גורם לגאווה.", "options_analysis": ["angry = כועס — לא מתאים לניצחון", "נכון! proud = גאה — תגובה טבעית לניצחון", "sad = עצוב — לא מתאים לניצחון", "thirsty = צמא — לא קשור לתחרות"]}', 1.49, -2.0, 0.25, 1, 'ai', NULL, true),
('28a27e40-3232-4405-903a-9404e67a8c75', 'sentence_completion', 'The baby started to ___ when she heard the loud noise.', NULL, '[{"id": "a", "text": "sleep"}, {"id": "d", "text": "laugh"}, {"id": "c", "text": "cry"}, {"id": "b", "text": "sing"}]'::jsonb, 2, '{"strategy": "loud noise = רעש חזק. איך תינוק מגיב לרעש פתאומי?", "correct_reason": "cry = לבכות. רעש חזק מפחיד תינוקות וגורם לבכי.", "options_analysis": ["sleep = לישון — רעש לא מרדים", "laugh = לצחוק — לא תגובה טבעית לרעש", "נכון! cry = לבכות — תגובה טבעית לרעש מפחיד", "sing = לשיר — לא תגובה לרעש"]}', 1.24, -2.0, 0.25, 1, 'ai', NULL, true),
('a88456ab-a1dc-468d-aea7-b6c4739245f3', 'sentence_completion', 'There were no clouds in the sky, so the weather was very ___.', NULL, '[{"id": "c", "text": "rainy"}, {"id": "b", "text": "foggy"}, {"id": "d", "text": "snowy"}, {"id": "a", "text": "sunny"}]'::jsonb, 3, '{"strategy": "no clouds = אין עננים. איזה מזג אוויר כשאין עננים?", "correct_reason": "sunny = שמשי. שמיים ללא עננים = שמש גלויה.", "options_analysis": ["rainy = גשום — גשם דורש עננים", "foggy = מעורפל — לא קשור לעננים", "snowy = מושלג — שלג דורש עננים", "נכון! sunny = שמשי — ללא עננים רואים שמש"]}', 1.29, -2.0, 0.25, 1, 'ai', NULL, true),
('2adb8063-2d5b-46eb-9cf5-1229262ecb85', 'sentence_completion', 'The library was completely ___, so everyone could concentrate on their books.', NULL, '[{"id": "b", "text": "quiet"}, {"id": "d", "text": "crowded"}, {"id": "a", "text": "dirty"}, {"id": "c", "text": "noisy"}]'::jsonb, 0, '{"strategy": "concentrate on books = להתרכז בספרים. איזו סביבה מאפשרת ריכוז?", "correct_reason": "quiet = שקטה. שקט מאפשר התרכזות.", "options_analysis": ["נכון! quiet = שקטה — שקט מאפשר ריכוז", "crowded = צפופה — לא בהכרח מאפשר ריכוז", "dirty = מלוכלכת — לא קשור לריכוז", "noisy = רועשת — רעש מפריע לריכוז"]}', 1.34, -2.0, 0.25, 1, 'ai', NULL, true),
('65fd26ce-515e-4ec1-a458-b56ed3fd84d8', 'sentence_completion', 'She forgot her umbrella, and now she is completely ___ from the rain.', NULL, '[{"id": "d", "text": "dry"}, {"id": "b", "text": "wet"}, {"id": "a", "text": "hungry"}, {"id": "c", "text": "warm"}]'::jsonb, 1, '{"strategy": "forgot umbrella + rain = שכחה מטרייה בגשם. מה קורה לה?", "correct_reason": "wet = רטובה. בלי מטרייה בגשם = מתרטבים.", "options_analysis": ["dry = יבשה — הפוך, בלי מטרייה נרטבים", "נכון! wet = רטובה — בלי מטרייה בגשם מתרטבים", "hungry = רעבה — לא קשור לגשם", "warm = חמה — לא קשור לגשם"]}', 1.35, -2.0, 0.25, 1, 'ai', NULL, true),
('6f07f954-c19e-4d71-a99c-b562035adcb6', 'sentence_completion', 'The movie was so ___ that everyone in the theater fell asleep.', NULL, '[{"id": "a", "text": "short"}, {"id": "b", "text": "exciting"}, {"id": "d", "text": "boring"}, {"id": "c", "text": "funny"}]'::jsonb, 2, '{"strategy": "everyone fell asleep = כולם נרדמו. איזה סרט גורם להירדמות?", "correct_reason": "boring = משעמם. סרט משעמם גורם להירדמות.", "options_analysis": ["short = קצר — אורך לא קשור לשינה", "exciting = מרגש — סרט מרגש לא מרדים", "נכון! boring = משעמם — משעמם גורם להירדמות", "funny = מצחיק — סרט מצחיק לא מרדים"]}', 1.41, -2.0, 0.25, 1, 'ai', NULL, true),
('d9fbdf3f-e167-4f35-b355-ca2fba759be7', 'sentence_completion', 'He ran five kilometers, so now he feels very ___.', NULL, '[{"id": "b", "text": "cold"}, {"id": "d", "text": "fresh"}, {"id": "c", "text": "bored"}, {"id": "a", "text": "tired"}]'::jsonb, 3, '{"strategy": "ran five kilometers = רץ חמישה קילומטרים. איך מרגישים אחרי ריצה ארוכה?", "correct_reason": "tired = עייף. ריצה ארוכה מעייפת.", "options_analysis": ["cold = קר — לא קשור למאמץ", "fresh = רענן — הפוך ממה שקורה אחרי ריצה", "bored = משועמם — ריצה היא פעילות, לא שעמום", "נכון! tired = עייף — תוצאה טבעית של ריצה ארוכה"]}', 1.43, -2.0, 0.25, 1, 'ai', NULL, true),
('55608934-f571-46d2-ba15-32d317b35c84', 'sentence_completion', 'The milk smelled bad, so she knew it had gone ___.', NULL, '[{"id": "d", "text": "sour"}, {"id": "c", "text": "sweet"}, {"id": "b", "text": "warm"}, {"id": "a", "text": "fresh"}]'::jsonb, 0, '{"strategy": "smelled bad = ריח רע. מה קורה לחלב כשהוא מתקלקל?", "correct_reason": "sour = חמוץ/מקולקל. ריח רע מעיד שהחלב התקלקל.", "options_analysis": ["נכון! sour = החמיץ — ריח רע מעיד שהחלב התקלקל", "sweet = מתוק — לא מתאר קלקול", "warm = חם — טמפרטורה לא קשורה לריח רע", "fresh = טרי — הפוך, ריח רע לא מעיד על טריות"]}', 1.51, -2.0, 0.25, 1, 'ai', NULL, true),
('504456f0-22a1-4819-b9ec-808222bbbe19', 'sentence_completion', 'The classroom was ___ because the teacher had not arrived yet.', NULL, '[{"id": "d", "text": "clean"}, {"id": "a", "text": "empty"}, {"id": "b", "text": "full"}, {"id": "c", "text": "loud"}]'::jsonb, 1, '{"strategy": "teacher had not arrived = המורה לא הגיעה עדיין. איך נראית כיתה בלי מורה ובלי תלמידים?", "correct_reason": "empty = ריקה. בלי מורה, יתכן שגם התלמידים עדיין לא נכנסו.", "options_analysis": ["clean = נקייה — לא קשור להגעת המורה", "נכון! empty = ריקה — לפני הגעת המורה הכיתה עדיין ריקה", "full = מלאה — לא הגיוני לפני שהשיעור התחיל", "loud = רועשת — כיתה ריקה לא רועשת"]}', 1.38, -2.0, 0.25, 1, 'ai', NULL, true),
('ade16f7d-536d-419c-8efc-ebc5a628fbc5', 'sentence_completion', 'Despite the committee''s initial skepticism, the proposal was eventually ___ due to its clear long-term benefits.', NULL, '[{"id": "d", "text": "postponed"}, {"id": "a", "text": "dismissed"}, {"id": "c", "text": "ratified"}, {"id": "b", "text": "ignored"}]'::jsonb, 2, '{"strategy": "eventually ___ due to clear benefits = בסופו של דבר אושרה בזכות היתרונות. חפש פועל של אישור רשמי.", "correct_reason": "ratified = אושרה רשמית. יתרונות ברורים הובילו לאישור למרות הספקנות ההתחלתית.", "options_analysis": ["postponed = נדחתה לזמן אחר — לא מסביר אישור סופי", "dismissed = נדחתה — סותר את ''due to clear benefits''", "נכון! ratified = אושרה רשמית — יתרונות הובילו לאישור", "ignored = התעלמו ממנה — סותר את קבלת ההצעה"]}', 1.4, 2.0, 0.25, 5, 'ai', NULL, true),
('3ba03979-78d8-4db7-8c79-fc3dd0466fd9', 'sentence_completion', 'The professor''s argument was so ___ that even his harshest critics struggled to find a flaw.', NULL, '[{"id": "a", "text": "vague"}, {"id": "d", "text": "trivial"}, {"id": "c", "text": "redundant"}, {"id": "b", "text": "cogent"}]'::jsonb, 3, '{"strategy": "critics struggled to find a flaw = מבקרים התקשו למצוא פגם. איזה טיעון קשה לתקוף?", "correct_reason": "cogent = משכנע ומוצק לוגית. טיעון כזה קשה לתקוף גם למבקרים קשוחים.", "options_analysis": ["vague = מעורפל — קל למצוא פגמים בטיעון מעורפל", "trivial = שולי/חסר חשיבות — לא היה מושך ביקורת קשה מלכתחילה", "redundant = מיותר/חוזר על עצמו — לא מסביר קושי במציאת פגם", "נכון! cogent = משכנע/הגיוני היטב — קשה למצוא בו פגם"]}', 1.1, 2.0, 0.25, 5, 'ai', NULL, true),
('7f315010-6549-4912-8d6c-ebed7fab12f6', 'sentence_completion', 'Her ___ approach to negotiations often left opponents uncertain about her true intentions.', NULL, '[{"id": "d", "text": "enigmatic"}, {"id": "c", "text": "predictable"}, {"id": "b", "text": "careless"}, {"id": "a", "text": "transparent"}]'::jsonb, 0, '{"strategy": "opponents uncertain about her true intentions = היריבים לא בטוחים בכוונותיה. איזו גישה יוצרת חוסר ודאות?", "correct_reason": "enigmatic = חידתית/בלתי ניתנת לפענוח. גישה כזו משאירה יריבים בחוסר ודאות.", "options_analysis": ["נכון! enigmatic = חידתית — יוצרת חוסר ודאות לגבי כוונות אמיתיות", "predictable = צפויה — הפוך, צפיות יוצרת ודאות", "careless = רשלנית — לא קשור ליצירת חוסר ודאות מכוון", "transparent = שקופה — הפוך, שקיפות לא יוצרת חוסר ודאות"]}', 1.51, 2.0, 0.25, 5, 'ai', NULL, true),
('a217635b-99d4-491f-b2e4-946406bec53b', 'sentence_completion', 'The new regulations were designed to ___ corruption within the organization.', NULL, '[{"id": "a", "text": "publicize"}, {"id": "d", "text": "curb"}, {"id": "c", "text": "overlook"}, {"id": "b", "text": "encourage"}]'::jsonb, 1, '{"strategy": "regulations designed to ___ corruption = תקנות שנועדו לטפל בשחיתות. מה עושים תקנות עם שחיתות?", "correct_reason": "curb = לרסן/לבלום. תקנות נועדו לרסן שחיתות, לא לעודד אותה.", "options_analysis": ["publicize = לפרסם — לא זו מטרת תקנות נגד שחיתות", "נכון! curb = לרסן/לבלום — תקנות נועדו לבלום שחיתות", "overlook = להתעלם מ- — סותר את מטרת התקנות", "encourage = לעודד — הפוך לגמרי ממטרת תקנות"]}', 1.16, 2.0, 0.25, 5, 'ai', NULL, true),
('378f5d37-f390-4f99-b799-772a54898146', 'sentence_completion', 'The scientist''s findings were later ___ by an independent team using more rigorous methods.', NULL, '[{"id": "c", "text": "invented"}, {"id": "a", "text": "forgotten"}, {"id": "d", "text": "corroborated"}, {"id": "b", "text": "mocked"}]'::jsonb, 2, '{"strategy": "independent team using rigorous methods = צוות עצמאי עם שיטות קפדניות. מה עשה הצוות לממצאים?", "correct_reason": "corroborated = אישש/חיזק. שיטות קפדניות משמשות בדרך כלל לאישוש ממצאים.", "options_analysis": ["invented = המציא — לא הגיוני עבור ממצאים קיימים", "forgotten = נשכחו — לא קשור לבדיקה מדעית", "נכון! corroborated = אישש/חיזק — צוות עצמאי מאשש ממצאים בשיטות קפדניות", "mocked = לעגו ל- — לא מתאר תהליך מדעי"]}', 1.24, 2.0, 0.25, 5, 'ai', NULL, true),
('795a81f9-1069-42e1-8d35-56b5d2f61968', 'sentence_completion', 'His ___ remarks during the meeting alienated several key stakeholders.', NULL, '[{"id": "a", "text": "tactful"}, {"id": "b", "text": "humble"}, {"id": "c", "text": "cautious"}, {"id": "d", "text": "brusque"}]'::jsonb, 3, '{"strategy": "alienated stakeholders = הרחיק/הרגיז בעלי עניין. איזה סוג הערות מרחיק אנשים?", "correct_reason": "brusque = גס/תקיף מדי. הערות כאלה מרחיקות ומעליבות אנשים.", "options_analysis": ["tactful = טקטית — הפוך, טקט לא מרחיק אנשים", "humble = צנועה — לא מסביר הרחקה", "cautious = זהירה — זהירות לא מרחיקה אנשים בדרך כלל", "נכון! brusque = גס/בוטה — הערות בוטות מרחיקות בעלי עניין"]}', 1.15, 2.0, 0.25, 5, 'ai', NULL, true),
('711c19bb-aa05-4791-a8ea-991a332f9136', 'sentence_completion', 'The economic downturn had a ___ effect on small businesses, forcing many to close.', NULL, '[{"id": "b", "text": "deleterious"}, {"id": "c", "text": "temporary"}, {"id": "d", "text": "favorable"}, {"id": "a", "text": "negligible"}]'::jsonb, 0, '{"strategy": "forcing many to close = אילץ רבים להיסגר. איזו השפעה גורמת לסגירת עסקים?", "correct_reason": "deleterious = מזיק/הרסני. השפעה כזו גורמת לסגירת עסקים.", "options_analysis": ["נכון! deleterious = מזיק/הרסני — הסבר לסגירת עסקים רבים", "temporary = זמנית — לא מוזכר במשפט וגם לא מסביר את חומרת הסגירה", "favorable = חיובית — הפוך ממה שקורה בסגירת עסקים", "negligible = זניח — סותר ''forcing many to close''"]}', 1.22, 2.0, 0.25, 5, 'ai', NULL, true),
('077ffe85-36db-4ec3-91d6-1bab0c05a2d6', 'sentence_completion', 'The senator''s speech was criticized as ___, offering grand promises without any concrete plan.', NULL, '[{"id": "d", "text": "measured"}, {"id": "c", "text": "vacuous"}, {"id": "b", "text": "specific"}, {"id": "a", "text": "substantive"}]'::jsonb, 1, '{"strategy": "grand promises without any concrete plan = הבטחות גדולות בלי תוכנית ממשית. איך מתארים נאום כזה?", "correct_reason": "vacuous = ריק מתוכן. הבטחות בלי תוכנית = נאום ריק מתוכן אמיתי.", "options_analysis": ["measured = מדוד/שקול — לא מתאר הבטחות גרנדיוזיות", "נכון! vacuous = ריק מתוכן — הבטחות בלי תוכנית ממשית", "specific = ספציפי — סותר ''without any concrete plan''", "substantive = מהותי — הפוך, נאום עם הבטחות ריקות אינו מהותי"]}', 1.09, 2.0, 0.25, 5, 'ai', NULL, true),
('a8fe1d75-8b69-434c-8b07-f4debebb7b6d', 'sentence_completion', 'Years of careful diplomacy finally managed to ___ tensions between the two nations.', NULL, '[{"id": "b", "text": "escalate"}, {"id": "d", "text": "provoke"}, {"id": "c", "text": "defuse"}, {"id": "a", "text": "ignore"}]'::jsonb, 2, '{"strategy": "years of careful diplomacy = שנות דיפלומטיה זהירה. מה דיפלומטיה עושה למתיחות?", "correct_reason": "defuse = לפרק/להרגיע מתיחות. זו התוצאה הרצויה של דיפלומטיה מוצלחת.", "options_analysis": ["escalate = להסלים — הפוך ממטרת הדיפלומטיה", "provoke = לעורר/להסית — הפוך ממטרת דיפלומטיה", "נכון! defuse = להרגיע/לפרק מתיחות — תוצאת דיפלומטיה מוצלחת", "ignore = להתעלם מ- — לא מסביר ''managed to''"]}', 1.36, 2.0, 0.25, 5, 'ai', NULL, true),
('eb43f6c2-d0c7-4961-b96f-c45f912561fb', 'sentence_completion', 'The novelist''s prose is often praised for its ___ clarity, conveying complex ideas in simple language.', NULL, '[{"id": "d", "text": "convoluted"}, {"id": "b", "text": "deceptive"}, {"id": "a", "text": "archaic"}, {"id": "c", "text": "lucid"}]'::jsonb, 3, '{"strategy": "conveying complex ideas in simple language = מעבירה רעיונות מורכבים בשפה פשוטה. איזו תכונה מתארת זאת?", "correct_reason": "lucid = בהיר/צלול. סגנון כתיבה שמעביר מורכבות בפשטות הוא בהיר.", "options_analysis": ["convoluted = מסובך — הפוך, המשפט מדגיש פשטות", "deceptive = מטעה — לא קשור לבהירות סגנון", "archaic = ארכאי/מיושן — לא קשור לבהירות", "נכון! lucid = בהיר/צלול — מתאים לכתיבה שמפשטת רעיונות מורכבים"]}', 1.41, 2.0, 0.25, 5, 'ai', NULL, true),
('ca070dbc-f6a6-44b2-b386-285cbf4f5181', 'restatement', 'Tom likes to read books every evening.', NULL, '[{"id": "b", "text": "Every evening, Tom enjoys reading books."}, {"id": "a", "text": "Tom reads books only in the morning."}, {"id": "d", "text": "Tom read a book only once."}, {"id": "c", "text": "Tom does not like reading books."}]'::jsonb, 0, '{"strategy": "זהה את המשמעות המרכזית: טום נהנה לקרוא בכל ערב.", "correct_reason": "''every evening Tom enjoys reading'' = אותה משמעות בדיוק, רק בסדר מילים שונה.", "options_analysis": ["נכון! זהה במשמעות — הרגל קריאה כל ערב", "''רק בבוקר'' סותר ''every evening''", "''רק פעם אחת'' סותר ''every evening''", "''לא אוהב לקרוא'' הפוך למקור"]}', 1.37, -2.0, 0.25, 1, 'ai', NULL, true),
('39484212-dd55-4d17-8c06-aa9ace31d670', 'restatement', 'The store closes at nine o''clock.', NULL, '[{"id": "c", "text": "The store closes before nine o''clock."}, {"id": "d", "text": "Nine o''clock is when the store closes."}, {"id": "a", "text": "The store never closes."}, {"id": "b", "text": "The store opens at nine o''clock."}]'::jsonb, 1, '{"strategy": "זהה את המשמעות: שעת הסגירה היא תשע.", "correct_reason": "ניסוח מחדש בסדר הפוך של אותה עובדה — שעת סגירה נשארת תשע.", "options_analysis": ["''לפני תשע'' משנה את השעה המדויקת", "נכון! אותה עובדה בדיוק בסדר מילים הפוך", "''אף פעם לא נסגרת'' סותר את המקור", "''נפתחת'' במקום ''נסגרת'' — הפוך למקור"]}', 1.4, -2.0, 0.25, 1, 'ai', NULL, true),
('03a291de-211b-46cd-8ee6-c78bc552a05e', 'restatement', 'Although it was raining, the children continued to play outside.', NULL, '[{"id": "d", "text": "It was not raining, so the children played outside."}, {"id": "a", "text": "The children stopped playing because of the rain."}, {"id": "b", "text": "The children kept playing outside despite the rain."}, {"id": "c", "text": "The children played inside because of the rain."}]'::jsonb, 2, '{"strategy": "although = למרות ש-. הילדים המשיכו לשחק למרות הגשם.", "correct_reason": "''kept playing despite the rain'' = המשיכו לשחק למרות הגשם — זהה למקור.", "options_analysis": ["''לא היה גשם'' סותר את המקור", "''הפסיקו בגלל הגשם'' סותר ''continued to play''", "נכון! ''המשיכו למרות הגשם'' = ''although raining, continued to play''", "''שיחקו בפנים'' סותר ''play outside''"]}', 1.51, -2.0, 0.25, 1, 'ai', NULL, true),
('ce7f9d01-0355-4aa7-9c60-c4e55b0ff66d', 'restatement', 'My sister is taller than me.', NULL, '[{"id": "d", "text": "My sister is shorter than me."}, {"id": "c", "text": "I am taller than my sister."}, {"id": "a", "text": "My sister and I are the same height."}, {"id": "b", "text": "I am shorter than my sister."}]'::jsonb, 3, '{"strategy": "אחותי גבוהה ממני = אני נמוך יותר ממנה.", "correct_reason": "היגד יחסי הפוך אך זהה במשמעות: אם היא גבוהה ממני, אני נמוך ממנה.", "options_analysis": ["''היא נמוכה ממני'' — הפוך למקור", "''אני גבוה ממנה'' — הפוך למקור", "''אותו גובה'' סותר את ההשוואה במקור", "נכון! יחס הפוך זהה במשמעות — נמוך ממנה = היא גבוהה ממני"]}', 1.24, -2.0, 0.25, 1, 'ai', NULL, true),
('8e10d5fc-77b3-4b4f-b292-5bcbe376989d', 'restatement', 'He finished his homework before dinner.', NULL, '[{"id": "b", "text": "By the time dinner started, he had already finished his homework."}, {"id": "c", "text": "He did not finish his homework."}, {"id": "a", "text": "He finished his homework during dinner."}, {"id": "d", "text": "He finished his homework after dinner."}]'::jsonb, 0, '{"strategy": "before dinner = לפני הארוחה. סיים לפני שהתחילה הארוחה.", "correct_reason": "''by the time dinner started, already finished'' = סיים עוד לפני תחילת הארוחה — זהה למקור.", "options_analysis": ["נכון! ''כבר סיים לפני שהארוחה התחילה'' = ''finished before dinner''", "''לא סיים'' סותר את העובדה שסיים", "''במהלך הארוחה'' סותר ''before dinner''", "''אחרי הארוחה'' סותר ''before dinner''"]}', 1.55, -2.0, 0.25, 1, 'ai', NULL, true),
('dc55712c-04fb-4c6c-bad4-4dbe0a672a3b', 'restatement', 'The museum was closed, so we went to the park instead.', NULL, '[{"id": "a", "text": "We went to the park before visiting the museum."}, {"id": "b", "text": "Because the museum was closed, we visited the park."}, {"id": "d", "text": "We went to the museum instead of the park."}, {"id": "c", "text": "The museum was open, so we did not go to the park."}]'::jsonb, 1, '{"strategy": "closed...instead = סגור...לכן הלכנו לחלופה. הסיבה-תוצאה נשמרת.", "correct_reason": "''because closed, visited the park'' = אותה סיבה-תוצאה כמו במקור.", "options_analysis": ["''לפני ביקור במוזיאון'' משנה את סדר האירועים ומרמז שכן ביקרו במוזיאון", "נכון! אותה סיבה-תוצאה: מוזיאון סגור → הלכו לפארק", "''הלכו למוזיאון במקום הפארק'' — הפוך למקור", "''המוזיאון היה פתוח'' סותר את המקור"]}', 1.25, -2.0, 0.25, 1, 'ai', NULL, true),
('d3448690-b7c3-4bd6-b9e8-a431e33f8454', 'restatement', 'Notwithstanding the substantial risks involved, the board approved the merger.', NULL, '[{"id": "a", "text": "The merger was approved because there were no risks involved."}, {"id": "d", "text": "The board rejected the merger because of the risks."}, {"id": "b", "text": "Although the risks were considerable, the board still approved the merger."}, {"id": "c", "text": "The board postponed its decision due to the risks."}]'::jsonb, 2, '{"strategy": "notwithstanding = למרות. הדירקטוריון אישר את המיזוג למרות הסיכונים.", "correct_reason": "''although risks were considerable, still approved'' = זהה למשמעות ''notwithstanding substantial risks, approved''.", "options_analysis": ["''אין סיכונים'' סותר ''substantial risks''", "''דחו את המיזוג'' — הפוך למקור, שם דווקא אישרו", "נכון! ''למרות שהסיכונים היו משמעותיים, עדיין אישרו'' = אותה משמעות בדיוק", "''דחו את ההחלטה'' לא מוזכר במקור — שם התקבלה החלטה סופית"]}', 1.58, 2.0, 0.25, 5, 'ai', NULL, true),
('4c916515-b092-4f42-ba6f-acb892385db8', 'restatement', 'Had the company invested in research earlier, it would not have lost its competitive edge.', NULL, '[{"id": "b", "text": "The company invested in research early and kept its competitive edge."}, {"id": "c", "text": "The company''s competitive edge was unrelated to its research investment."}, {"id": "d", "text": "The company plans to invest in research in the future."}, {"id": "a", "text": "The company lost its competitive edge because it failed to invest in research earlier."}]'::jsonb, 3, '{"strategy": "משפט תנאי שלישי הפוך (Had it invested...would not have lost) = בפועל לא השקיעה ולכן איבדה יתרון.", "correct_reason": "''lost edge because failed to invest earlier'' = המשמעות ההפוכה הנכונה של תנאי שלישי — לא השקיעה, ולכן איבדה.", "options_analysis": ["''השקיעה מוקדם ושמרה יתרון'' — הפוך מהמצב בפועל שמתואר במשפט", "''לא קשור'' סותר את הקשר הסיבתי המפורש במשפט", "''מתכננת להשקיע בעתיד'' לא מוזכר ולא נובע מהמשפט", "נכון! תנאי שלישי הפוך: ''לא השקיעה מוקדם'' → ''איבדה יתרון'' — זו המשמעות בפועל"]}', 1.26, 2.0, 0.25, 5, 'ai', NULL, true),
('3ecf00f2-b7c4-4071-b281-baee1092ef42', 'restatement', 'The policy, while well-intentioned, ultimately exacerbated the very problem it sought to solve.', NULL, '[{"id": "d", "text": "Despite its good intentions, the policy made the problem worse."}, {"id": "c", "text": "The policy had no effect on the problem at all."}, {"id": "a", "text": "The policy was poorly intentioned from the start."}, {"id": "b", "text": "The policy successfully solved the problem it addressed."}]'::jsonb, 0, '{"strategy": "while well-intentioned...exacerbated = כוונות טובות אך החמיר את הבעיה.", "correct_reason": "''despite good intentions, made the problem worse'' = exacerbated = החמיר, זהה למקור.", "options_analysis": ["נכון! ''למרות כוונות טובות, החמירה את הבעיה'' = ''well-intentioned...exacerbated''", "''לא הייתה לה השפעה'' סותר ''exacerbated''", "''כוונות רעות מלכתחילה'' סותר ''well-intentioned''", "''פתרה בהצלחה'' — הפוך ל-''exacerbated'' (החמירה)"]}', 1.04, 2.0, 0.25, 5, 'ai', NULL, true),
('c881eea9-329d-4c49-b7a5-1b1d5c0b1642', 'restatement', 'Unless the funding is secured by next month, the research project will be indefinitely suspended.', NULL, '[{"id": "c", "text": "Funding has already been secured for the project."}, {"id": "b", "text": "The research project will be suspended if funding is not obtained by next month."}, {"id": "d", "text": "The project was suspended last month due to lack of funding."}, {"id": "a", "text": "The research project will continue regardless of funding."}]'::jsonb, 1, '{"strategy": "unless = אלא אם כן. אם לא יאובטח מימון עד החודש הבא — יושעה הפרויקט.", "correct_reason": "''will be suspended if funding is not obtained'' = תנאי הפוך זהה ל-''unless funding secured, suspended''.", "options_analysis": ["''המימון כבר אובטח'' סותר את מצב אי-הוודאות במקור", "נכון! ''יושעה אם לא יושג מימון'' = אותו תנאי בדיוק כמו ''unless funding secured''", "''הושעה החודש שעבר'' משנה את ציר הזמן — במקור מדובר בעתיד מותנה", "''ימשיך ללא קשר למימון'' סותר את התנאי במקור"]}', 1.42, 2.0, 0.25, 5, 'ai', NULL, true),
('51d25feb-78d3-4ca9-932f-0a91871161f4', 'restatement', 'It was only after reviewing the evidence meticulously that the jury reached its verdict.', NULL, '[{"id": "b", "text": "The evidence was inconclusive, so the jury could not reach a verdict."}, {"id": "c", "text": "The jury reviewed the evidence after announcing its verdict."}, {"id": "a", "text": "The jury reached its verdict only after a careful review of the evidence."}, {"id": "d", "text": "The jury reached its verdict without reviewing the evidence."}]'::jsonb, 2, '{"strategy": "only after reviewing meticulously = רק אחרי בדיקה קפדנית הגיעו לפסק דין.", "correct_reason": "''reached verdict only after careful review'' = meticulously = בקפדנות/בזהירות רבה, זהה למקור.", "options_analysis": ["''הראיות לא היו חד משמעיות'' לא מוזכר במקור כלל", "''בדקו אחרי שהכריזו על הפסק'' — הופך את סדר האירועים", "נכון! ''הגיעו לפסק דין רק אחרי בדיקה קפדנית'' = אותו סדר וסיבתיות כמו במקור", "''בלי לבדוק ראיות'' סותר ''reviewing the evidence meticulously''"]}', 1.04, 2.0, 0.25, 5, 'ai', NULL, true),
('79b917f7-3e05-4a0c-a1ea-4f62417adb54', 'restatement', 'Rarely has a debut novel received such unanimous critical acclaim.', NULL, '[{"id": "a", "text": "This debut novel received mixed reviews from critics."}, {"id": "c", "text": "Critics have often praised debut novels this highly before."}, {"id": "d", "text": "The novel was criticized by nearly all reviewers."}, {"id": "b", "text": "This debut novel was praised by critics almost unanimously, which is unusual."}]'::jsonb, 3, '{"strategy": "rarely...unanimous acclaim = נדיר שרומן ביכורים זוכה להערכה כה גורפת מהמבקרים.", "correct_reason": "''praised almost unanimously, which is unusual'' = משמר גם את העובדה (שבח גורף) וגם את הנדירות (rarely).", "options_analysis": ["''ביקורות מעורבות'' סותר ''unanimous critical acclaim''", "''לעיתים קרובות בעבר'' סותר את ''rarely'' — המקור מדגיש שזה נדיר", "''ביקורת שלילית מכולם'' הפוך גמור ל-''critical acclaim''", "נכון! שומר את השבח הגורף ואת אלמנט הנדירות (''rarely'') כאחד"]}', 1.43, 2.0, 0.25, 5, 'ai', NULL, true),
('57645cf4-9235-4f0b-b722-f0a71150f44f', 'reading_comprehension', 'What is the passage mainly about?', 'e0539593-0ef1-4965-91b3-7626bea45c15', '[{"id": "a", "text": "A group of neighbors creating and enjoying a community garden"}, {"id": "d", "text": "A town without any parks"}, {"id": "b", "text": "A school that grew its own vegetables"}, {"id": "c", "text": "How to grow tomatoes in the summer"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה מתארת יצירת גינה קהילתית ואת חיי השכונה סביבה.", "correct_reason": "הפסקה כולה עוסקת בשכנים שיוצרים ונהנים מגינה קהילתית.", "options_analysis": ["נכון! יצירת גינה קהילתית והחיים סביבה = הנושא הכולל", "לא נאמר בפסקה כלל", "לא מדויק — הגינה לא שייכת לבית הספר, רק ממוקמת לידו", "פרט טכני שמוזכר, לא הנושא המרכזי"]}', 1.26, -2.0, 0.25, 1, 'ai', NULL, true),
('5129e652-d740-43ea-ac66-443239abdf8d', 'reading_comprehension', 'Where did the neighbors build the garden?', 'e0539593-0ef1-4965-91b3-7626bea45c15', '[{"id": "c", "text": "Behind the town hall"}, {"id": "b", "text": "On an empty lot behind the school"}, {"id": "d", "text": "In a park downtown"}, {"id": "a", "text": "On someone''s private farm"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את המיקום המדויק בפסקה.", "correct_reason": "הפסקה אומרת: ''an empty lot behind the school''.", "options_analysis": ["לא נאמר בפסקה", "נכון! נאמר במפורש ''empty lot behind the school''", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.34, -2.0, 0.25, 1, 'ai', NULL, true),
('200d8cd1-8973-481a-9b48-bd55224719a0', 'reading_comprehension', 'When did families visit the garden?', 'e0539593-0ef1-4965-91b3-7626bea45c15', '[{"id": "c", "text": "Only in winter"}, {"id": "d", "text": "Once a month"}, {"id": "a", "text": "Every weekend"}, {"id": "b", "text": "Every morning"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש את תדירות הביקורים.", "correct_reason": "הפסקה אומרת: ''Families visited the garden every weekend''.", "options_analysis": ["סותר את הפסקה — הגינה פרחה בקיץ", "לא נאמר בפסקה", "נכון! נאמר במפורש ''every weekend''", "לא נאמר בפסקה"]}', 1.42, -2.0, 0.25, 1, 'ai', NULL, true),
('7f3ca2ad-6960-4b2f-b6e2-9c3be053cc25', 'reading_comprehension', 'The word "weeds" in the passage most closely means:', 'e0539593-0ef1-4965-91b3-7626bea45c15', '[{"id": "b", "text": "a kind of vegetable"}, {"id": "c", "text": "types of flowers"}, {"id": "a", "text": "small garden tools"}, {"id": "d", "text": "unwanted plants growing among the crops"}]'::jsonb, 3, '{"strategy": "אוצר מילים בהקשר — ''pull out weeds'' = לעקור עשבים לא רצויים.", "correct_reason": "weeds = עשבים שוטים/לא רצויים שגדלים בין הצמחים ומעכבים אותם.", "options_analysis": ["הפסקה מבדילה בין weeds לירקות שבכוונה שתלו", "הפסקה מבדילה בין weeds לפרחים (flowers) שבכוונה שתלו", "לא קשור לכלים", "נכון! weeds = עשבים לא רצויים שצריך לעקור"]}', 1.24, -2.0, 0.25, 1, 'ai', NULL, true),
('9af67424-176e-465d-84f4-6683fd8d50c3', 'reading_comprehension', 'What happened to the vegetables the neighbors grew?', 'e0539593-0ef1-4965-91b3-7626bea45c15', '[{"id": "b", "text": "They were shared with everyone in the town"}, {"id": "d", "text": "They were given only to the school"}, {"id": "c", "text": "They were sold at a market"}, {"id": "a", "text": "They were thrown away"}]'::jsonb, 0, '{"strategy": "שאלת פרט — מה נעשה עם התוצרת בסוף הפסקה.", "correct_reason": "הפסקה מסתיימת: ''The neighbors shared the vegetables with everyone in the town''.", "options_analysis": ["נכון! נאמר במפורש בסוף הפסקה", "לא נאמר בפסקה — שותף עם כל העיר, לא רק בית הספר", "לא נאמר בפסקה", "סותר לגמרי את הפסקה"]}', 1.33, -2.0, 0.25, 1, 'ai', NULL, true),
('f2091c52-dac0-450e-9b27-88e01ab93b43', 'reading_comprehension', 'What is the main idea of the passage?', '55aa6fc8-c55e-4c73-bd29-9598fc65eebb', '[{"id": "a", "text": "Economic theory has been proven entirely correct about choice"}, {"id": "c", "text": "Having too many choices can reduce, rather than increase, consumer satisfaction"}, {"id": "b", "text": "Businesses should always offer as many products as possible"}, {"id": "d", "text": "Consumers always prefer the largest possible selection"}]'::jsonb, 1, '{"strategy": "שאלת רעיון מרכזי — הפסקה מציגה את ''פרדוקס הבחירה'': יותר מדי אפשרויות עלול להזיק.", "correct_reason": "כל הפסקה בנויה סביב הרעיון שריבוי אפשרויות מעבר לסף מסוים פוגע בשביעות רצון.", "options_analysis": ["הפוך — הפסקה מראה שהתיאוריה הכלכלית הקלאסית מאותגרת ע''י מחקר פסיכולוגי", "נכון! פרדוקס הבחירה — ריבוי אפשרויות עלול להפחית שביעות רצון", "מסקנה קיצונית מדי; הפסקה מציגה את ההפך — עסקים מצמצמים בחירה", "הפוך — הפסקה מראה שלא תמיד; יותר מדי בחירה יוצרת חרדה"]}', 1.58, 2.0, 0.25, 5, 'ai', NULL, true),
('6273f251-5fbc-4700-9f78-f7efa36fb5ac', 'reading_comprehension', 'According to conventional economic theory, what should more choice lead to?', '55aa6fc8-c55e-4c73-bd29-9598fc65eebb', '[{"id": "c", "text": "Less need for advertising"}, {"id": "a", "text": "Greater anxiety and confusion"}, {"id": "d", "text": "Greater satisfaction, since people can find exactly what they prefer"}, {"id": "b", "text": "Lower sales for businesses"}]'::jsonb, 2, '{"strategy": "שאלת פרט — מה טוענת התיאוריה הכלכלית הקונבנציונלית.", "correct_reason": "הפסקה אומרת: ''greater choice should lead to greater satisfaction, since individuals are better able to select the option that precisely matches their preferences''.", "options_analysis": ["לא נאמר בפסקה כלל", "זו טענת המחקר הפסיכולוגי החדש, לא של התיאוריה הכלכלית הקלאסית", "נכון! נאמר במפורש כטענת התיאוריה הקלאסית", "לא נאמר בפסקה כלל"]}', 1.13, 2.0, 0.25, 5, 'ai', NULL, true),
('0a67f8c7-1f10-42bc-a2b6-6d0fa3d78d56', 'reading_comprehension', 'The word "curating" in the passage most closely means:', '55aa6fc8-c55e-4c73-bd29-9598fc65eebb', '[{"id": "a", "text": "advertising aggressively"}, {"id": "d", "text": "randomly increasing"}, {"id": "b", "text": "removing completely"}, {"id": "c", "text": "carefully selecting and organizing"}]'::jsonb, 3, '{"strategy": "אוצר מילים בהקשר — ''deliberately curating smaller, more manageable selections''.", "correct_reason": "curating = בחירה וארגון מכוונים וקפדניים של מבחר מוצרים.", "options_analysis": ["לא קשור לפרסום", "הפוך — לא הגדלה אקראית אלא צמצום מכוון", "הפוך — לא הסרה מוחלטת אלא מבחר מצומצם ומאורגן", "נכון! curating = בחירה וארגון קפדניים ומכוונים"]}', 1.59, 2.0, 0.25, 5, 'ai', NULL, true),
('eff080b1-423e-4bbe-9b03-4eb18458cc6c', 'reading_comprehension', 'Why does the author mention that businesses are now offering smaller selections?', '55aa6fc8-c55e-4c73-bd29-9598fc65eebb', '[{"id": "b", "text": "To illustrate a practical response to research on the paradox of choice"}, {"id": "d", "text": "To criticize psychological research"}, {"id": "c", "text": "To argue that businesses are losing money"}, {"id": "a", "text": "To prove that conventional economic theory is completely wrong"}]'::jsonb, 0, '{"strategy": "שאלת מטרת המחבר — המשפט האחרון מדגים יישום מעשי של הממצאים שתוארו קודם.", "correct_reason": "המחבר מביא את דוגמת העסקים כהמחשה לכך שהמחקר על פרדוקס הבחירה משפיע בפועל על התנהגות עסקית.", "options_analysis": ["נכון! דוגמה מעשית ליישום הממצאים שתוארו בפסקה", "המחבר מציג את המחקר הפסיכולוגי בצורה חיובית, לא ביקורתית", "לא נאמר בפסקה שעסקים מפסידים כסף", "הפסקה לא טוענת שהתיאוריה הכלכלית שגויה לחלוטין, רק שהיא מאותגרת"]}', 1.09, 2.0, 0.25, 5, 'ai', NULL, true),
('f14649b8-9a3e-43d0-8534-7d4ded96c93e', 'reading_comprehension', 'According to the passage, what happens as the number of choices increases beyond a certain point?', '55aa6fc8-c55e-4c73-bd29-9598fc65eebb', '[{"id": "b", "text": "People spend less time deciding"}, {"id": "a", "text": "People experience more anxiety, decision paralysis, and regret"}, {"id": "c", "text": "People become less interested in shopping"}, {"id": "d", "text": "People feel more confident about their decisions"}]'::jsonb, 1, '{"strategy": "שאלת פרט — מה קורה כשמספר האפשרויות עולה על סף מסוים.", "correct_reason": "הפסקה אומרת: ''people frequently experience heightened anxiety, decision paralysis, and post-decision regret''.", "options_analysis": ["הפוך — ''decision paralysis'' מרמז על התלבטות ממושכת יותר, לא פחות", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה כלל", "הפוך — הפסקה מתארת ירידה בביטחון, לא עלייה"]}', 1.45, 2.0, 0.25, 5, 'ai', NULL, true);